<script setup>import{Head}from'@inertiajs/vue3';import AppLayout from'../Layouts/AppLayout.vue';import StandingsTable from'../Components/StandingsTable.vue';import EmptyState from'../Components/EmptyState.vue';defineProps({current:Object,standings:Array,captains:Array,ownership:Array});</script><template><Head title="Live"/><AppLayout><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="label">{{current?.name||'Gameweek'}} command centre</p><h1 class="mt-2 text-4xl font-black">Live room.</h1><p class="mt-2 text-[#718078]">Captain blocs, league ownership and provisional scores.</p></div><span class="rounded-full bg-red-100 px-4 py-2 text-xs font-black uppercase tracking-widest text-red-600 dark:bg-red-950/40">● Live data</span></div><template v-if="standings.length"><div class="mt-8 grid gap-6 lg:grid-cols-2"><section class="card p-6"><h2 class="text-xl font-black">Captaincy battle</h2><div class="mt-6 space-y-5"><div v-for="c in captains"><div class="flex justify-between"><b>{{c.name}}</b><span>{{c.count}} captain{{c.count===1?'':'s'}}</span></div><div class="my-2 h-2 rounded-full bg-[#e4e9e5] dark:bg-[#20332a]"><div class="h-full rounded-full bg-[#f4d35e]" :style="{width:`${c.count/standings.length*100}%`}"></div></div><small class="text-[#718078]">{{c.managers.join(', ')}}</small></div></div></section><section class="card p-6"><h2 class="text-xl font-black">Mini-league ownership</h2><div class="mt-6 grid grid-cols-2 gap-3"><div v-for="o in ownership" class="rounded-xl bg-[#edf1ec] p-3 dark:bg-[#172a21]"><b>{{o.name}}</b><span class="block text-2xl font-black">{{o.percent}}%</span></div></div></section></div><div class="mt-7"><StandingsTable :rows="standings"/></div></template><EmptyState v-else class="mt-8" title="Waiting for the first squad reveal" text="Captaincy and ownership become available after FPL publishes the gameweek picks."/></AppLayout></template>
